document.addEventListener("click",e=>{let button=e.target.closest("button");if(!button||button.disabled)return;let candidate={button,form:null};pendingActionCandidate=candidate;queueMicrotask(()=>{if(pendingActionCandidate===candidate)pendingActionCandidate=null})},true);
