async function api(url,opt){let candidate=pendingActionCandidate;pendingActionCandidate=null;let restore=null,form=candidate?.form;if(candidate&&!form)restore=setButtonBusy(candidate.button,pendingLabel(url,opt,candidate.button));if(form&&!pendingFormRestores.has(form))lockPendingForm(form,candidate.button);try{if(window.roundsSupabaseSetupError)throw Error(window.roundsSupabaseSetupError);if(window.roundsSupabase)return await window.roundsSupabase.api(url,opt);let r=await fetch(url,{credentials:"same-origin",headers:{"Content-Type":"application/json"},...(opt||{})});let j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.error||"Request failed.");return j}catch(error){if(form)releasePendingForm(form);throw error}finally{restore?.()}}
function toast(title,msg,type){let isError=type==="error"||/^(could not|unable to|delete failed)/i.test(title),n=document.createElement("div");if(isError)document.querySelectorAll("#dialog form[data-pending=true]").forEach(releasePendingForm);n.className="toast"+(isError?" toast-error":"");n.setAttribute("role",isError?"alert":"status");n.innerHTML='<span class="toast-mark">'+ico(isError?"alert":"check",12)+'</span><div class="toast-copy"><strong>'+esc(title)+'</strong>'+esc(msg||"")+'</div>';$("#toast-region").append(n);setTimeout(()=>n.remove(),3800)}
function showFormError(form,message){if(!form)return;releasePendingForm(form);let error=form.querySelector(".form-error");if(!error){error=document.createElement("div");error.className="form-error";error.setAttribute("role","alert");error.tabIndex=-1;form.prepend(error)}error.textContent=message||"Could not save. Review the form and try again.";error.focus({preventScroll:false})}
function isArchivedRecord(item){return !!item&&(item.archived===true||item.active===false)}
function isArchivedLocation(room){if(!room)return true;let building=s.data?.buildings.find(item=>item.id===room.buildingId);return isArchivedRecord(room)||isArchivedRecord(building)}
function archiveTabs(kind,activeCount,archivedCount){let current=s.archiveView[kind]||"active";return '<div class="archive-tabs" role="group" aria-label="Record filter"><button class="archive-tab'+(current==="active"?" selected":"")+'" type="button" data-action="archive-view" data-kind="'+kind+'" data-view="active" aria-pressed="'+(current==="active")+'">Active <span>'+activeCount+'</span></button><button class="archive-tab'+(current==="archived"?" selected":"")+'" type="button" data-action="archive-view" data-kind="'+kind+'" data-view="archived" aria-pressed="'+(current==="archived")+'">Archived <span>'+archivedCount+'</span></button></div>'}
