function recordActions(entity,id,label,archived,inherited){if(s.data.demo)return"";return '<div class="record-actions">'+recordButton("record-edit",entity,id,"Edit "+label,"edit")+(inherited?"":recordButton(archived?"record-restore":"record-archive",entity,id,(archived?"Restore ":"Archive ")+label,archived?"restore":"archive"))+recordButton("record-delete",entity,id,"Delete "+label,"trash")+'</div>'}
function confirmAction(title,description,label,danger){return new Promise(resolve=>{let accepted=false;dialog(title,description,'<p class="confirm-copy">'+esc(danger?"This action is permanent. Use Archive when you need to keep the record and its history.":"Archived records disappear from active staff workflows and can be restored later.")+'</p>','<button class="button" data-action="close">Cancel</button><button class="button '+(danger?"delete":"primary")+'" id="confirm-action" type="button">'+esc(label)+'</button>');let d=$("#dialog");d.addEventListener("close",()=>resolve(accepted),{once:true});$("#confirm-action").onclick=()=>{accepted=true;d.close()}})}
function archiveEntityName(entity){return({buildings:"Building",rooms:"Room",schedules:"Schedule",users:"IT Staff account"})[entity]||"Record"}
async function archiveRecord(entity,id,archived,label,button){
  let verb=archived?"archive":"restore";
  return withButtonBusy(button,(archived?"Archiving ":"Restoring ")+label.toLowerCase()+".",async()=>{
    try{await api("/api/"+entity+"/"+encodeURIComponent(id),{method:"PATCH",body:JSON.stringify({archived})});await load();toast(label+(archived?" archived":" restored"),archived?"It can be restored from the Archived view.":"It is available in active workspace lists again.")}
    catch(error){toast("Could not "+verb+" "+label.toLowerCase(),error.message,"error")}
  })
}
function deleteFailureMessage(error){let message=String(error?.message||"");if(/uploaded room-check photos/i.test(message))return "This account has uploaded room-check photos. Archive it to preserve those records.";if(/23503|foreign key|violates.*constraint|constraint.*violat/i.test(message))return "Other records still depend on this item. Archive it instead so check history stays intact.";return message||"The record could not be deleted."}
function recordDisplayName(entity,id,fallback){
  let list=entity==="buildings"?s.data.buildings:entity==="rooms"?s.data.rooms:entity==="schedules"?s.data.schedules:s.data.users,item=list?.find(x=>x.id===id);
  if(!item)return fallback;
  if(entity==="rooms")return "Room "+(item.roomNumber||"")+" · "+(item.name||"Unnamed room");
  if(entity==="schedules")return (item.course||"Schedule")+" · "+(item.instructor||"");
  return item.name||fallback;
}
async function deleteEntity(entity,id,label,button){
  let name=recordDisplayName(entity,id,label);
  if(!await confirmAction("Delete "+name+"?","This permanently removes the "+label+". Existing check history can prevent deletion.","Delete permanently",true))return;
  return withButtonBusy(button,"Deleting "+label.toLowerCase()+".",async()=>{
    try{await api("/api/"+entity+"/"+encodeURIComponent(id),{method:"DELETE"});await load();toast(label+" deleted","The record was permanently removed.")}
    catch(error){toast("Could not delete "+label.toLowerCase(),deleteFailureMessage(error),"error")}
  })
}
function statusOf(t){if(t.issueStatus==="open")return"issue";if(t.issueStatus==="resolved")return"resolved";if(t.completedAt)return"checked";let start=new Date(t.date+"T"+t.schedule.startTime+":00+08:00").getTime(),delta=Date.now()-start;if(delta>25*60000)return"overdue";if(t.claimedBy)return"progress";return delta<0?"upcoming":"due"}
function labelStatus(x){return({due:"Due now",overdue:"Overdue",checked:"Checked",issue:"Issue open",progress:"In progress",upcoming:"Upcoming",resolved:"Resolved"})[x]||x}
const tasks=()=>(s.data?.rounds||[]).filter(t=>!isArchivedLocation(s.data.rooms.find(r=>r.id===t.room.id)));
function statusSignature(){return tasks().map(t=>t.id+":"+statusOf(t)).join("|")}
function liveStatus(){return '<span class="network-state '+(s.live?"online":"offline")+'">'+(s.live?"Live updates":"Connecting")+'</span>'}
function counts(){let a=tasks().map(statusOf);return{total:a.length,due:a.filter(x=>x==="due"||x==="progress").length,over:a.filter(x=>x==="overdue").length,issue:a.filter(x=>x==="issue").length,done:a.filter(x=>x==="checked"||x==="resolved").length,up:a.filter(x=>x==="upcoming").length}}
function nav(){let a=[["overview","grid","Overview"],["rounds","rounds","Room rounds"],["schedule","calendar","Schedule"],["rooms","building","Buildings & rooms"],["team","users","Team"],["activity","activity","Activity"]];return s.user.role==="admin"?a:a.filter(x=>["overview","rounds","activity"].includes(x[0]))}
