function navItem(item,mobile){let id=item[0],n=id==="rounds"?tasks().filter(t=>["due","overdue","issue"].includes(statusOf(t))).length:0,active=id==="schedule"?(s.page==="schedule"||s.page==="schedule-planner"):s.page===id;return '<button class="'+(mobile?"mobile-nav-link":"nav-link")+(active?" active":"")+'" data-page="'+id+'">'+ico(item[1])+'<span>'+esc(mobile&&id==="rooms"?"Buildings":item[2])+'</span>'+(!mobile&&id==="rounds"?'<span class="nav-count" data-pending-count '+(n?"":"hidden")+'>'+n+"</span>":"")+"</button>"}
