function login(error,email){
  app.innerHTML='<main class="login-shell"><section class="login-story"><div class="brand"><div class="brand-mark"><span></span><span></span><span></span></div><div class="brand-copy"><span class="brand-name">Rounds</span><span class="brand-meta">IT room checks</span></div></div><div class="login-story-content"><div class="login-eyebrow">Campus IT operations</div><h1 class="login-heading">Every room,<br><em>accounted for.</em></h1><p class="login-story-copy">A shared rounds queue for classroom handoffs, equipment checks, and issues that need follow-up.</p><div class="login-feature-strip"><span class="login-feature">'+ico("calendar")+'Schedule-led checks</span><span class="login-feature">'+ico("monitor")+'Room PC and display status</span><span class="login-feature">'+ico("users")+'Shared across the team</span></div></div><div class="login-story-foot">Responsive workspace for desktop and mobile rounds.</div></section><section class="login-panel"><div class="login-card"><div class="login-brand"><div class="brand-mark"><span></span><span></span><span></span></div><span class="brand-name">Rounds</span>'+themeToggleButton()+'</div><h2 class="login-title">Sign in to your workspace</h2><p class="login-subtitle">Use your Admin or IT Staff account to continue.</p><form class="login-form" id="login-form"><label class="form-field"><span class="form-label">Work email</span><input class="text-input" name="email" type="email" autocomplete="username" placeholder="name@school.edu" value="'+esc(email||"")+'" required></label><label class="form-field"><span class="form-label">Password</span><input class="text-input" name="password" type="password" autocomplete="current-password" required></label><div class="login-error '+(error?"show":"")+'" role="alert">'+esc(error||"")+'</div><button class="button primary login-submit">Sign in</button></form><div class="login-help">Use the account created in Supabase Auth.</div></div></section></main>';
  if(error)$("#login-form [name=password]").focus();
  $("#login-form").onsubmit=async e=>{e.preventDefault();let f=new FormData(e.currentTarget);try{let r=await api("/api/login",{method:"POST",body:JSON.stringify({email:f.get("email"),password:f.get("password")})});s.user=r.user;await load();connect()}catch(err){login(err.message,f.get("email"))}}
}
