function activity(limit,interactive){
  let all=s.data.audit||[],a=interactive?all.slice():all.slice(0,limit||20);
  if(interactive){
    let state=s.lists.activity;
    if(state.search){let q=state.search.toLowerCase();a=a.filter(x=>(x.action+" "+x.detail+" "+x.actor).toLowerCase().includes(q))}
    a=sortList(a,{date:(x,y)=>new Date(x.createdAt)-new Date(y.createdAt),action:(x,y)=>textCompare(x.action,y.action),person:(x,y)=>textCompare(x.actor,y.actor)},state.sort);
    a=a.slice(0,limit||50);
  }
  if(!a.length){
    let title=interactive&&s.lists.activity.search?"No activity matches your search":"No activity recorded yet";
    let copy=interactive&&s.lists.activity.search?"Try a different search or reset the list filters.":"Updates to staff, schedules, rooms, and checks will appear here.";
    return '<div class="activity-empty"><strong>'+esc(title)+'</strong><span>'+esc(copy)+'</span></div>';
  }
  return '<div class="activity-list">'+a.map(x=>'<div class="activity-item"><span class="activity-mark"></span><div class="activity-copy"><strong>'+esc(x.action)+'</strong> · '+esc(x.detail)+'<span class="activity-time">'+esc(x.actor)+' · '+new Intl.DateTimeFormat("en-PH",{timeZone:"Asia/Manila",hour:"numeric",minute:"2-digit"}).format(new Date(x.createdAt))+"</span></div></div>").join("")+"</div>";
}
function overview(){let c=counts(),acts=s.user.role==="admin"?'<button class="button" data-action="import">'+ico("upload")+'Import Excel</button><button class="button primary" data-action="schedule">'+ico("plus")+'Add schedule</button>':'<button class="button primary" data-page="rounds">'+ico("rounds")+'Open my rounds</button>',list=tasks().filter(t=>["due","overdue","issue","progress","upcoming"].includes(statusOf(t))).slice(0,5);let cover=s.data.buildings.filter(b=>!isArchivedRecord(b)).map(b=>{let a=tasks().filter(t=>t.building?.id===b.id),done=a.filter(t=>["checked","resolved"].includes(statusOf(t))).length,p=a.length?Math.round(done/a.length*100):0;return '<div class="coverage-row"><span class="coverage-name">'+esc(b.name)+'</span><span class="coverage-track"><span class="coverage-fill" style="display:block;width:'+p+'%"></span></span><span class="coverage-value">'+done+'/'+a.length+'</span></div>'}).join("");return heading(s.user.role==="admin"?"Room rounds overview":"Your room rounds",s.user.role==="admin"?"Today’s room handoffs and check status across campus.":"Rooms that need your attention, sorted by scheduled handoff.",acts)+'<section class="stats-grid">'+stat("Checks today",c.total,"scheduled","","rounds","Across active room schedules")+stat("Due / in progress",c.due,c.due?"Needs a check or is in progress":"No check pending",c.due?"warn":"","clock","Triggered by instructor handoffs")+stat("Overdue",c.over,c.over?"Needs follow-up":"All checks on time",c.over?"warn":"good","alert","Unfinished for more than 25 minutes")+stat("Open issues",c.issue,c.issue?"Requires follow-up":"No open display issues",c.issue?"warn":"good","monitor","Display or laptop/HDMI findings")+'</section>'+(c.issue?'<div class="page-alert">'+ico("alert",14)+' '+c.issue+' room issue(s) need follow-up. Issues stay open until resolved.</div>':"")+'<section class="panel"><div class="panel-head"><div><h2 class="panel-title">Room checks</h2><span class="panel-sub">'+esc(dateLabel())+' · Instructor handoffs and room status</span></div><button class="button small subtle" data-page="rounds">View all</button></div>'+(list.length?'<div class="round-list">'+list.map(row).join("")+'</div><div class="panel-foot"><span>'+c.done+' checked · '+c.up+' upcoming</span>'+liveStatus()+'</div>':empty("No room checks scheduled","Add a room schedule to create the first handoff check.",s.user.role==="admin"?'<button class="button small" data-action="schedule">'+ico("plus")+'Add schedule</button>':""))+'</section><div class="panel-grid"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Building coverage</h2><span class="panel-sub">Checks completed today</span></div>'+(s.user.role==="admin"?'<button class="button small subtle" data-page="rooms">Manage rooms</button>':'')+'</div>'+(cover?'<div class="coverage-list">'+cover+"</div>":empty("No buildings yet","Add a building to organize rooms."))+'</section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Recent activity</h2><span class="panel-sub">Latest changes from the team</span></div><button class="button small subtle" data-page="activity" data-activity-view="team">View all</button></div>'+activity(4)+"</section></div>"}
function roundsPage(){let state=s.lists.rounds,a=tasks();if(state.building!=="all")a=a.filter(t=>t.building.id===state.building);if(state.status!=="all")a=a.filter(t=>statusOf(t)===state.status);if(state.search){let q=state.search.toLowerCase();a=a.filter(t=>(t.room.name+" "+t.room.roomNumber+" "+t.building.name+" "+t.schedule.instructor+" "+t.schedule.course+" "+t.schedule.section).toLowerCase().includes(q))}a=sortList(a,{time:(x,y)=>x.schedule.startTime.localeCompare(y.schedule.startTime),room:(x,y)=>textCompare(x.room.roomNumber,y.room.roomNumber),building:(x,y)=>textCompare(x.building.name,y.building.name),instructor:(x,y)=>textCompare(x.schedule.instructor,y.schedule.instructor),status:(x,y)=>textCompare(labelStatus(statusOf(x)),labelStatus(statusOf(y)))},state.sort);let statuses=[["all","All statuses"],["due","Due now"],["overdue","Overdue"],["progress","In progress"],["checked","Checked"],["resolved","Resolved"],["issue","Issue open"],["upcoming","Upcoming"]],filters=[{key:"building",label:"Filter by building",options:[["all","All buildings"],...s.data.buildings.map(b=>[b.id,b.name])]},{key:"status",label:"Filter by status",options:statuses}],sorts=[["time_asc","Time: earliest"],["time_desc","Time: latest"],["room_asc","Room: low to high"],["room_desc","Room: high to low"],["building_asc","Building: A–Z"],["instructor_asc","Instructor: A–Z"],["status_asc","Status"]];return heading("Room rounds","Check scheduled instructor handoffs and record what you find.")+'<section class="panel">'+listControls("rounds","Search rooms, buildings, or instructors",sorts,filters)+(a.length?'<div class="round-list">'+a.map(row).join("")+'</div><div class="panel-foot"><span>'+a.length+' checks</span>'+liveStatus()+'</div>':empty("No checks match these filters","Adjust the filters or reset them to see more rounds."))+"</section>"}
function scheduleRow(x){let r=s.data.rooms.find(y=>y.id===x.roomId),b=r&&s.data.buildings.find(y=>y.id===r.buildingId),days=x.days.map(d=>DAYS[d]).join(", "),inherited=!x.archived&&isArchivedLocation(r),hidden=!!x.archived||inherited,state=hidden?(x.archived?"Archived":"Hidden by location"):x.active?"Active":"Paused",actions=s.data.demo?"":recordButton("edit-schedule","schedules",x.id,"Edit schedule","edit")+(hidden?"":'<button class="icon-button record-action" data-action="toggle-schedule" data-id="'+esc(x.id)+'" aria-label="'+(x.active?'Pause':'Resume')+' schedule" title="'+(x.active?'Pause':'Resume')+' schedule">'+ico(x.active?'pause':'play',15)+'</button>')+(inherited?"":recordButton(x.archived?"record-restore":"record-archive","schedules",x.id,(x.archived?"Restore":"Archive")+" schedule",x.archived?"restore":"archive"))+recordButton("record-delete","schedules",x.id,"Delete schedule","trash");return '<div class="schedule-row '+(hidden?'archived':x.active?'':'paused')+'"><div class="schedule-room">'+esc(b?.code||"-")+' · '+esc(r?.roomNumber||"Room")+'</div><div><span class="schedule-instructor">'+esc(x.instructor)+'</span><span class="schedule-section">'+esc(x.section||"Instructor")+'</span></div><div class="schedule-course">'+esc(x.course)+'</div><div class="schedule-time">'+fmtTime(x.startTime)+'-'+fmtTime(x.endTime)+'<span class="schedule-section">'+esc(days)+'</span></div><div class="schedule-action"><span class="schedule-state '+(hidden?'paused':x.active?'active':'paused')+'">'+esc(state)+'</span>'+actions+'</div></div>'}
